import unittest
from templates.service import expand_all

class Templates(unittest.TestCase):
    def test_chains_escapes_and_shared_dependencies(self):
        values={'URL':'${BASE}/${NAME}','BASE':'${ROOT}/v2','ROOT':'srv','NAME':'${ROOT}','LITERAL':'$${ROOT}','EMPTY':'','COST':'$$5 ${EMPTY}','RAW':'$x ${bad-key}'}
        before=values.copy()
        self.assertEqual(expand_all(values),{'URL':'srv/v2/srv','BASE':'srv/v2','ROOT':'srv','NAME':'srv','LITERAL':'${ROOT}','EMPTY':'','COST':'$5 ','RAW':'$x ${bad-key}'})
        self.assertEqual(values,before)
        self.assertEqual(expand_all({}),{})
        self.assertEqual(expand_all({'X':'$${ABSENT}'}),{'X':'${ABSENT}'})
    def test_missing_and_cycles(self):
        with self.assertRaises(KeyError): expand_all({'A':'${ABSENT}'})
        for values in [{'A':'${A}'},{'A':'${B}','B':'${C}','C':'${A}'}]:
            with self.assertRaises(ValueError): expand_all(values)
        self.assertEqual(expand_all({'A':'${C}','B':'${C}','C':'leaf'}),{'A':'leaf','B':'leaf','C':'leaf'})

if __name__ == '__main__':
    unittest.main()

