from .tokens import tokenize

def resolve(values):
    memo={}
    active=set()
    def visit(key):
        if key in memo:
            return memo[key]
        if key in active:
            raise ValueError('template cycle')
        active.add(key)
        try:
            result=''.join(visit(value) if kind == 'ref' else value
                           for kind,value in tokenize(values[key]))
            memo[key]=result
            return result
        finally:
            active.remove(key)
    return {key:visit(key) for key in values}

